import random
import string
from typing import List

# Generator for space-delimited protocol tokens used by NUT text protocol.
# We focus on producing plausible command lines/tokens that the target
# fuzzers feed into upscli_get/list_start/list_next via FUZZ_PARAM_STR.
#
# Strategy
# - Produce between 1 and 4 tokens (the fuzz stubs limit MAXQ=4).
# - Prefer known subcommands and shapes to exercise parser branches:
#   GET, LIST with various sub-subcommands like VAR/VAR all, CMD, CLIENTS, UPSDESC, etc.
# - Include realistic device, variable, and command names, numeric ports, and values.
# - Ensure tokens have no internal spaces and remain ASCII.
# - Keep total size <= 4096 bytes.
#
# The returned bytes is a single buffer that contains one logical "line" worth
# of tokens separated by single spaces. Fuzzer infra will split to supply tokens.

KNOWN_DEVICES = [
    "ups", "main", "dev0", "rackPDU", "eaton", "apc_smart", "tripp", "srv01", "edgeUPS",
]

# Common variable names in NUT
KNOWN_VARS = [
    "battery.charge", "battery.runtime", "battery.voltage", "ups.status", "ups.load",
    "input.voltage", "output.voltage", "driver.version", "device.mfr", "device.model",
    "ups.test.result", "ups.timer.start", "ups.timer.shutdown",
]

# Variables that are typically RW in many drivers
KNOWN_RW_VARS = [
    "ups.delay.start", "ups.delay.shutdown", "ups.id", "ups.description",
]

# Common command names
KNOWN_CMDS = [
    "test.battery.start", "test.battery.stop", "beeper.enable", "beeper.disable",
    "shutdown.return", "shutdown.stayoff", "shutdown.stop", "load.off", "load.on",
]

# Helper token producers
ALNUM = string.ascii_letters + string.digits + "._-:/@"


def _rand_ident(rng: random.Random, min_len=3, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(ALNUM) for _ in range(n))


def _rand_device(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(KNOWN_DEVICES)
    return _rand_ident(rng)


def _rand_var(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(KNOWN_VARS)
    # dot-separated segments typical in NUT vars
    segs = [
        ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 7)))
        for _ in range(rng.randint(1, 3))
    ]
    return '.'.join(segs)


def _rand_cmd(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(KNOWN_CMDS)
    segs = [
        ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 8)))
        for _ in range(rng.randint(1, 3))
    ]
    return '.'.join(segs)


def _rand_value(rng: random.Random) -> str:
    # Values in protocol tokens are often quoted server-side, but our fuzz harness
    # provides tokens without spaces; keep them compact.
    choices = [
        str(rng.randint(0, 10000)),
        f"{rng.uniform(0, 100.0):.1f}",
        _rand_ident(rng, 3, 16),
        "enabled", "disabled", "on", "off",
    ]
    return rng.choice(choices)


def _make_get_tokens(rng: random.Random) -> List[str]:
    # Shapes seen in NUT protocol:
    # GET VAR <ups> <var>
    # GET NUMLOGINS <ups>
    # GET UPSDESC <ups>
    # GET RID <tracking-id>
    sub = rng.choice(["VAR", "NUMLOGINS", "UPSDESC", "RID"]) if rng.random() < 0.9 else _rand_ident(rng).upper()
    if sub == "VAR":
        return ["GET", "VAR", _rand_device(rng), _rand_var(rng)]
    if sub == "NUMLOGINS":
        return ["GET", "NUMLOGINS", _rand_device(rng)]
    if sub == "UPSDESC":
        return ["GET", "UPSDESC", _rand_device(rng)]
    if sub == "RID":
        # Tracking IDs are often integers or small strings
        rid = str(rng.randint(1, 100000)) if rng.random() < 0.8 else _rand_ident(rng, 4, 12)
        return ["GET", "RID", rid]
    # Fallback generic 2..4 token GET
    toks = ["GET", _rand_ident(rng).upper()]
    if rng.random() < 0.8:
        toks.append(_rand_ident(rng))
    if rng.random() < 0.5:
        toks.append(_rand_ident(rng))
    return toks


def _make_list_tokens(rng: random.Random) -> List[str]:
    # LIST subcommands:
    # LIST VAR <ups>
    # LIST RW <ups>
    # LIST CMD <ups>
    # LIST CLIENTS <ups>
    sub = rng.choice(["VAR", "RW", "CMD", "CLIENTS"]) if rng.random() < 0.95 else _rand_ident(rng).upper()
    return ["LIST", sub, _rand_device(rng)]


def _make_set_tokens(rng: random.Random) -> List[str]:
    # SET VAR <ups> <var> <value>
    var = rng.choice(KNOWN_RW_VARS) if rng.random() < 0.7 else _rand_var(rng)
    return ["SET", "VAR", _rand_device(rng), var, _rand_value(rng)]


def _make_instcmd_tokens(rng: random.Random) -> List[str]:
    # INSTCMD <ups> <command> [param]
    toks = ["INSTCMD", _rand_device(rng), _rand_cmd(rng)]
    if rng.random() < 0.4:
        toks.append(_rand_value(rng))
    return toks


def _make_login_tokens(rng: random.Random) -> List[str]:
    # LOGIN <ups>
    return ["LOGIN", _rand_device(rng)]


def _make_master_tokens(rng: random.Random) -> List[str]:
    # MASTER <ups>  or  PRIMARY <ups>
    cmd = rng.choice(["MASTER", "PRIMARY"])
    return [cmd, _rand_device(rng)]


def _make_fsd_tokens(rng: random.Random) -> List[str]:
    # FSD <ups>
    return ["FSD", _rand_device(rng)]


def _choose_template(rng: random.Random) -> List[str]:
    makers = [
        _make_get_tokens,
        _make_list_tokens,
        _make_set_tokens,
        _make_instcmd_tokens,
        _make_login_tokens,
        _make_master_tokens,
        _make_fsd_tokens,
    ]
    weights = [0.22, 0.22, 0.16, 0.16, 0.08, 0.08, 0.08]
    maker = rng.choices(makers, weights=weights, k=1)[0]
    return maker(rng)


def _ensure_protocol_constraints(tokens: List[str]) -> List[str]:
    # Ensure no spaces and ASCII; trim overly long tokens to keep total size small
    out = []
    for t in tokens:
        # Replace spaces (should not exist) and enforce ASCII subset
        t2 = ''.join(ch if ch in ALNUM else '_' for ch in t)
        if len(t2) > 128:
            t2 = t2[:128]
        out.append(t2)
    # Cap the number of tokens to 4 as per fuzzer stub MAXQ
    return out[:4]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly pick a template and maybe perturb with slight variations
    tokens = _choose_template(rng)

    # Occasionally shorten to exercise 1..4 token paths in fuzzers
    if rng.random() < 0.1:
        tokens = tokens[:rng.randint(1, min(4, len(tokens)))]

    tokens = _ensure_protocol_constraints(tokens)

    # Join with single spaces as expected by the harness, ending with optional newline
    line = ' '.join(tokens)
    if len(line) > 4096:
        line = line[:4096]
    # Newline-terminated buffer can be helpful, but not required; keep random
    if rng.random() < 0.5 and not line.endswith('\n'):
        line += '\n'
    return line.encode('ascii', errors='ignore')

import random
import string
from typing import List

# Generator for NUT protocol command lines (ASCII). The fuzzer stubs will
# take the bytes we produce and may truncate to 1024 bytes; keep <=4096.
# We strive to craft valid protocol requests that exercise different server
# code paths.

# Common NUT protocol verbs and subcommands
VERBS = [
    # Top-level
    "GET", "LIST", "SET", "INSTCMD", "LOGIN", "LOGOUT",
    "USERNAME", "PASSWORD", "STARTTLS", "VER", "HELP",
]

GET_SUBCMDS = [
    # device-level queries
    ("UPSDESC", ["ups"]),
    ("VAR", ["ups", "var"]),
    ("TYPE", ["ups", "var"]),
    ("RW", ["ups", "var"]),
    ("CMDDESC", ["ups", "cmd"]),
]

LIST_SUBCMDS = [
    ("UPS", []),
    ("VAR", ["ups"]),
    ("RW", ["ups"]),
    ("CMD", ["ups"]),
    ("CLIENT", ["ups"]),
]

SET_FORMS = [
    ("VAR", ["ups", "var", "value"]),
]

INSTCMD_FORMS = [
    ("", ["ups", "cmd"]),
    ("withparam", ["ups", "cmd", "param"]),
]

# Some plausible UPS/variable/command names
UPS_NAMES = [
    "ups", "ups1", "dev0", "main", "rack-01", "srv_ups", "ΔUPS", "x"*32
]
VAR_NAMES = [
    "battery.charge", "battery.runtime", "input.voltage", "output.voltage",
    "ups.status", "ups.load", "device.model", "device.mfr",
]
CMD_NAMES = [
    "test.battery.start", "test.battery.stop", "beeper.enable", "beeper.disable",
    "shutdown.return", "shutdown.stayoff", "load.off", "load.on",
]

STATUS_TOKENS = ["OL", "OB", "LB", "RB", "CHRG", "DISCHRG", "TRIM", "BOOST"]

def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return rng.choice(seq)

def _rand_ident(rng: random.Random, base_choices: List[str]) -> str:
    # Optionally quote or escape values with spaces
    s = _rand_choice(rng, base_choices)
    # Occasionally produce a quoted token with spaces to exercise escaping
    if rng.random() < 0.2:
        extras = [" ", "_", "-", ".", ":"]
        s2 = s + rng.choice(extras) + ''.join(rng.choice(string.ascii_letters) for _ in range(rng.randint(1,5)))
        return '"' + s2 + '"'
    return s

def _rand_value(rng: random.Random) -> str:
    # Produce a realistic value: number, float, string, or status list
    t = rng.random()
    if t < 0.25:
        return str(rng.randint(-10000, 100000))
    if t < 0.5:
        return f"{rng.uniform(-1000.0, 1000.0):.2f}"
    if t < 0.75:
        # status token list space-delimited
        k = rng.randint(1, 4)
        return ' '.join(rng.sample(STATUS_TOKENS, k))
    # quoted string value possibly with spaces
    s = ''.join(rng.choice(string.ascii_letters + string.digits + ' .:_-') for _ in range(rng.randint(3, 16)))
    if ' ' in s:
        return '"' + s + '"'
    return s

def _build_get(rng: random.Random) -> str:
    sub, fields = _rand_choice(rng, GET_SUBCMDS)
    tokens = ["GET", sub]
    for f in fields:
        if f == "ups":
            tokens.append(_rand_ident(rng, UPS_NAMES))
        elif f == "var":
            tokens.append(_rand_ident(rng, VAR_NAMES))
        elif f == "cmd":
            tokens.append(_rand_ident(rng, CMD_NAMES))
    return ' '.join(tokens)

def _build_list(rng: random.Random) -> str:
    sub, fields = _rand_choice(rng, LIST_SUBCMDS)
    tokens = ["LIST", sub]
    for f in fields:
        if f == "ups":
            tokens.append(_rand_ident(rng, UPS_NAMES))
    return ' '.join(tokens)

def _build_set(rng: random.Random) -> str:
    sub, fields = _rand_choice(rng, SET_FORMS)
    tokens = ["SET", sub]
    for f in fields:
        if f == "ups":
            tokens.append(_rand_ident(rng, UPS_NAMES))
        elif f == "var":
            tokens.append(_rand_ident(rng, VAR_NAMES))
        elif f == "value":
            tokens.append(_rand_value(rng))
    return ' '.join(tokens)

def _build_instcmd(rng: random.Random) -> str:
    form, fields = _rand_choice(rng, INSTCMD_FORMS)
    tokens = ["INSTCMD"]
    for f in fields:
        if f == "ups":
            tokens.append(_rand_ident(rng, UPS_NAMES))
        elif f == "cmd":
            tokens.append(_rand_ident(rng, CMD_NAMES))
        elif f == "param":
            tokens.append(_rand_value(rng))
    return ' '.join(tokens)

def _build_auth(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return "USERNAME " + _rand_ident(rng, ["admin", "user", "operator", "guest"]) 
    else:
        # Include special chars and quotes sometimes
        pw = ''.join(rng.choice(string.ascii_letters + string.digits + "!@#$_- ") for _ in range(rng.randint(4,12)))
        if ' ' in pw:
            pw = '"' + pw + '"'
        return "PASSWORD " + pw

def _build_simple(rng: random.Random) -> str:
    verb = _rand_choice(rng, ["HELP", "VER", "LOGOUT"])
    if verb == "HELP" and rng.random() < 0.5:
        # sometimes ask help for a topic
        topic = _rand_choice(rng, ["GET", "LIST", "SET", "INSTCMD", "LOGIN"])
        return f"HELP {topic}"
    return verb

def _build_starttls(rng: random.Random) -> str:
    # Some servers accept STARTTLS optionally with a policy token
    if rng.random() < 0.3:
        return "STARTTLS OPTIONAL"
    return "STARTTLS"

def _maybe_chain(rng: random.Random, parts: List[str]) -> str:
    # Build a sequence of commands separated by newlines to exercise pipeline
    # Behavior; still valid as multiple lines. The fuzzer may send up to 1024 bytes.
    if not parts:
        return "\n"
    lines: List[str] = []
    budget = 1000  # keep under 1024 generally
    for p in parts:
        if len(p) + 1 <= budget:
            lines.append(p)
            budget -= (len(p) + 1)
        else:
            break
    return "\n".join(lines) + "\n"

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    builders = [
        _build_get,
        _build_list,
        _build_set,
        _build_instcmd,
        _build_auth,
        _build_simple,
        _build_starttls,
    ]
    # Create a small script of commands to cover diverse paths
    parts: List[str] = []

    # Sometimes begin with authentication dance
    if rng.random() < 0.7:
        parts.append("LOGIN") if rng.random() < 0.2 else None
        parts.append(_build_auth(rng))
        parts.append(_build_auth(rng)) if rng.random() < 0.5 else None

    # Often probe server capabilities/version
    if rng.random() < 0.6:
        parts.append("VER")

    # Add a mix of query/list/set/instcmd commands
    count = rng.randint(2, 6)
    for _ in range(count):
        b = rng.choice(builders[:4])  # favor protocol data-bearing ops
        parts.append(b(rng))
        # Occasionally interleave HELP/STARTTLS
        if rng.random() < 0.2:
            parts.append(_build_simple(rng))
        if rng.random() < 0.15:
            parts.append(_build_starttls(rng))

    # Optionally finish with logout
    if rng.random() < 0.5:
        parts.append("LOGOUT")

    payload = _maybe_chain(rng, parts)
    # Ensure ASCII bytes and size cap
    data = payload.encode('ascii', errors='ignore')[:4096]
    return data

import random
import string
from typing import List, Tuple

# Generator for UPS identifier strings accepted by upscli_splitname
# Based on NUT conventions, typical formats include:
#  - ups@host
#  - ups@host:port
#  - @host (no ups name)
#  - ups@[ipv6]
#  - ups@[ipv6]:port
#  - ups@ipv4
#  - ups@hostname.local
#  - ups@host:service (some implementations may parse numeric only; we stick to numeric ports mostly)
#  - Variants with underscores, dashes, dots in names
#  - Edge cases: empty ups name, empty host, missing port, large/small port values
# The fuzzer stub passes a std::string to upscli_splitname, so we just return bytes
# representing a plausible and interesting identifier string.

SAFE_UPS_CHARS = string.ascii_letters + string.digits + "_-+."
SAFE_HOST_CHARS = string.ascii_lowercase + string.digits + "-."


def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return rng.choice(items)


def _rand_upsname(rng: random.Random) -> str:
    # UPS names in NUT are generally token-like without spaces
    # Include cases: short, long, with punctuation
    length = rng.choice([0, 1, 3, 5, 8, 12, 20])
    if length == 0:
        return ""
    return ''.join(rng.choice(SAFE_UPS_CHARS) for _ in range(length))


def _rand_ipv4(rng: random.Random) -> str:
    # Include broadcast-ish and edge values occasionally
    specials = [
        "127.0.0.1", "0.0.0.0", "255.255.255.255", "192.168.0.1", "10.0.0.1",
        "169.254.1.1", "8.8.8.8"
    ]
    if rng.random() < 0.3:
        return rng.choice(specials)
    return '.'.join(str(rng.randint(0, 255)) for _ in range(4))


def _rand_ipv6(rng: random.Random) -> str:
    # Generate a variety of IPv6 textual forms without validation complexity
    # Sometimes compressed, sometimes full, sometimes IPv4-mapped
    def hextet():
        n = rng.randint(0, 0xFFFF)
        return format(n, 'x')

    choice = rng.random()
    if choice < 0.25:
        # Full 8 hextets
        addr = ':'.join(hextet() for _ in range(8))
    elif choice < 0.5:
        # Compressed with :: once
        left = [hextet() for _ in range(rng.randint(1, 6))]
        right = [hextet() for _ in range(rng.randint(0, 6 - len(left)))]
        addr = ':'.join(left) + '::' + (':'.join(right) if right else '')
    elif choice < 0.75:
        # IPv4-mapped
        addr = '::ffff:' + _rand_ipv4(rng)
    else:
        # Link-local with zone id (zone id usually after %; include sometimes)
        base = 'fe80::' + hextet()
        if rng.random() < 0.5:
            base += '%' + rng.choice(['eth0', 'en0', 'wlan0', '1'])
        addr = base
    return '[' + addr + ']'


def _rand_hostname(rng: random.Random) -> str:
    # Generate DNS-like hostnames, sometimes with domain, sometimes single label
    if rng.random() < 0.3:
        return _rand_ipv4(rng)
    if rng.random() < 0.2:
        return _rand_ipv6(rng)
    labels = []
    nlabels = rng.choice([1, 2, 3, 4])
    for i in range(nlabels):
        # Ensure label does not start/end with hyphen, keep alnum and hyphen
        length = rng.randint(1, 15)
        s = ''.join(rng.choice(string.ascii_lowercase + string.digits + '-') for _ in range(length))
        # fix start/end
        if s[0] == '-':
            s = 'a' + s[1:]
        if s[-1] == '-':
            s = s[:-1] + 'z'
        labels.append(s)
    host = '.'.join(labels)
    # Occasionally append a localdomain or unusual TLD
    if rng.random() < 0.3:
        host += rng.choice(['.local', '.lan', '.example', '.corp'])
    return host


def _rand_port(rng: random.Random) -> str:
    # Prefer numeric ports; include edge values
    specials = ["0", "1", "22", "53", "123", "3493", "65535"]
    if rng.random() < 0.4:
        return rng.choice(specials)
    return str(rng.randint(2, 65534))


def _build_identifier(rng: random.Random) -> str:
    upsname = _rand_upsname(rng)
    host = _rand_hostname(rng)

    # Decide on including port
    include_port = rng.random() < 0.7
    port = _rand_port(rng) if include_port else None

    # Sometimes omit upsname entirely, sometimes omit host (rare),
    # but maintain validity: need at least host for parser usefulness.
    pattern = _rand_choice(rng, [
        'ups_at_host',
        'ups_at_host_port',
        'at_host',
        'at_host_port',
    ])

    # Ensure we have a non-empty upsname if pattern requires it
    if pattern.startswith('ups') and not upsname:
        upsname = 'ups' + str(rng.randint(0, 999))

    if pattern == 'ups_at_host':
        return f"{upsname}@{host}"
    if pattern == 'ups_at_host_port' and port is not None:
        return f"{upsname}@{host}:{port}"
    if pattern == 'at_host':
        return f"@{host}"
    if pattern == 'at_host_port' and port is not None:
        return f"@{host}:{port}"
    # Fallbacks
    if port is not None:
        return f"{upsname or 'ups'}@{host}:{port}"
    return f"{upsname or 'ups'}@{host}"


def _sprinkle_whitespace(rng: random.Random, s: str) -> str:
    # Some parsers tolerate leading/trailing whitespace; include occasionally
    if rng.random() < 0.2:
        s = s.lstrip()  # no-op
    pads = [' ', '\t', '']
    left = rng.choice(pads)
    right = rng.choice(pads)
    return left + s + right


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose one of several interesting categories with weights
    category = rng.choices(
        population=[
            'basic',          # typical ups@host
            'with_port',      # ups@host:port
            'ipv6',           # ups@[ipv6]
            'ipv6_port',      # ups@[ipv6]:port
            'host_only',      # @host
            'edge_ports',     # ports at extremes or service-like
            'long_names',     # long ups/host parts
        ],
        weights=[30, 25, 12, 8, 10, 8, 7],
        k=1
    )[0]

    if category == 'basic':
        s = _build_identifier(rng)
    elif category == 'with_port':
        s = _build_identifier(rng)
        if ':' not in s:
            s += ':' + _rand_port(rng)
    elif category == 'ipv6':
        ups = _rand_upsname(rng) or 'ups'
        host = _rand_ipv6(rng)
        s = f"{ups}@{host}"
    elif category == 'ipv6_port':
        ups = _rand_upsname(rng) or 'ups'
        host = _rand_ipv6(rng)
        s = f"{ups}@{host}:{_rand_port(rng)}"
    elif category == 'host_only':
        s = '@' + _rand_hostname(rng)
    elif category == 'edge_ports':
        ups = _rand_upsname(rng) or 'ups'
        host = _rand_hostname(rng)
        s = f"{ups}@{host}:{rng.choice(['0','1','65535'])}"
    elif category == 'long_names':
        rng_len = rng.randint(16, 64)
        ups = ''.join(rng.choice(SAFE_UPS_CHARS) for _ in range(rng_len))
        # Build a reasonably long hostname with multiple labels
        labels = []
        for _ in range(rng.randint(3, 6)):
            llen = rng.randint(10, 20)
            lbl = ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(llen))
            labels.append(lbl)
        host = '.'.join(labels)
        s = f"{ups}@{host}:{_rand_port(rng)}"
    else:
        s = _build_identifier(rng)

    s = _sprinkle_whitespace(rng, s)

    # Ensure length bound
    s = s[:4096]
    return s.encode('utf-8', errors='ignore')

import random
import string
from typing import List

# Generator for valid "host:port" strings accepted by upscli_splitaddr
# It should cover:
# - hostnames (with labels per RFC rules), optional ports
# - IPv4 literals, optional ports
# - IPv6 literals in brackets with optional ports; also bare IPv6 without port
# - Edge cases like localhost, empty host with port ":3493" if permitted, and service-like names
# - Reasonable port ranges (0..65535), including defaults like 3493
# Results are seeded and vary per call.

MAX_LEN = 4096
DEFAULT_PORT = 3493

_letters = string.ascii_letters
_digits = string.digits
_hyphen = "-"
_label_chars = _letters + _digits + _hyphen


def _rand_int(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _pick(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]


def _gen_hostname_label(rng: random.Random) -> str:
    # Labels: 1..63, alnum at ends, may contain hyphen inside
    length = _rand_int(rng, 1, 20)
    if length == 1:
        return _pick(rng, list(_letters + _digits)).lower()
    inner_len = max(0, length - 2)
    start = _pick(rng, list(_letters + _digits)).lower()
    end = _pick(rng, list(_letters + _digits)).lower()
    inner = ''.join(rng.choice(_label_chars) for _ in range(inner_len)).lower()
    return start + inner + end


def _gen_hostname(rng: random.Random) -> str:
    # Generate between 1 and 5 labels
    specials = ["localhost", "ups", "nut", "server", "example", "host"]
    if rng.random() < 0.2:
        base = _pick(rng, specials)
        if rng.random() < 0.5:
            tlds = ["local", "lan", "test", "example", "com", "org", "net"]
            return base + "." + _pick(rng, tlds)
        return base
    nlabels = _rand_int(rng, 1, 4)
    labels = [_gen_hostname_label(rng) for _ in range(nlabels)]
    # Sometimes add a common TLD
    if rng.random() < 0.6:
        tlds = ["com", "org", "net", "local", "lan", "example"]
        labels.append(_pick(rng, tlds))
    return '.'.join(labels)


def _gen_ipv4(rng: random.Random) -> str:
    # Include common and boundary octets
    octet_choices = [0, 1, 10, 127, 169, 172, 192, 198, 223, 255]
    def octet():
        if rng.random() < 0.5:
            return _rand_int(rng, 0, 255)
        return _pick(rng, octet_choices)
    return f"{octet()}.{octet()}.{octet()}.{octet()}"


def _gen_ipv6_hextet(rng: random.Random) -> str:
    # 1 to 4 hex digits
    n = _rand_int(rng, 1, 4)
    return ''.join(rng.choice('0123456789abcdef') for _ in range(n))


def _gen_ipv6(rng: random.Random) -> str:
    # Generate various IPv6 textual forms, including :: compression
    # Build full 8 hextets then apply compression
    hextets = [_gen_ipv6_hextet(rng) for _ in range(8)]
    # Optionally embed IPv4 in last two hextets
    if rng.random() < 0.2:
        ipv4 = _gen_ipv4(rng)
        # Replace last two hextets with IPv4
        hextets[-2:] = [ipv4]
        text = ':'.join(hextets)
    else:
        text = ':'.join(hextets)
    # Apply zero-compression sometimes
    if rng.random() < 0.7:
        parts = text.split(':')
        # Find a run of zeros to compress; approximate by replacing a random run
        zero_runs = []
        start = None
        for i, p in enumerate(parts):
            if p == '0' or p == '0000':
                if start is None:
                    start = i
            else:
                if start is not None:
                    zero_runs.append((start, i - 1))
                    start = None
        if start is not None:
            zero_runs.append((start, len(parts) - 1))
        if not zero_runs and rng.random() < 0.3:
            # Introduce a zero run manually
            idx = _rand_int(rng, 0, len(parts) - 2)
            parts[idx] = '0'
            parts[idx + 1] = '0'
            zero_runs = [(idx, idx + 1)]
        if zero_runs:
            s, e = _pick(rng, zero_runs)
            # Compress this run
            new_parts = []
            i = 0
            while i < len(parts):
                if s <= i <= e:
                    if not new_parts or new_parts[-1] != '':
                        new_parts.append('')
                    i = e + 1
                    continue
                new_parts.append(parts[i])
                i += 1
            if new_parts and new_parts[0] == '':
                new_parts = [''] + new_parts  # ensure leading :: if start at 0
            if new_parts and new_parts[-1] == '':
                pass  # allow trailing ::
            text = ':'.join(new_parts)
            # Normalize consecutive colons
            while ':::' in text:
                text = text.replace(':::', '::')
    # Optionally uppercase hex
    if rng.random() < 0.3:
        text = text.upper()
    return text


def _maybe_port(rng: random.Random) -> str:
    # Generate optional :port with realistic and boundary ports
    if rng.random() < 0.6:
        port_choices = [0, 1, 7, 9, 13, 37, 80, 123, 443, 1024, 2049, 31337, DEFAULT_PORT, 49152, 65535]
        if rng.random() < 0.5:
            port = _rand_int(rng, 0, 65535)
        else:
            port = _pick(rng, port_choices)
        return f":{port}"
    return ""


def _gen_hostport(rng: random.Random) -> str:
    kind = rng.choices(
        population=["hostname", "ipv4", "ipv6_br", "ipv6_bare", "just_port", "userstyle"],
        weights=[35, 20, 25, 10, 5, 5],
        k=1,
    )[0]

    if kind == "hostname":
        host = _gen_hostname(rng)
        return host + _maybe_port(rng)
    if kind == "ipv4":
        host = _gen_ipv4(rng)
        return host + _maybe_port(rng)
    if kind == "ipv6_br":
        host = _gen_ipv6(rng)
        return f"[{host}]" + _maybe_port(rng)
    if kind == "ipv6_bare":
        # Bare IPv6 without brackets; only valid when no port present
        host = _gen_ipv6(rng)
        return host
    if kind == "just_port":
        # Empty host with port like ":3493" (some parsers treat empty host as localhost)
        return _maybe_port(rng) or f":{DEFAULT_PORT}"
    if kind == "userstyle":
        # Common aliases
        choices = [
            "localhost",
            "localhost:" + str(DEFAULT_PORT),
            "ups.example.com",
            "nut-server",
            "[::1]:" + str(DEFAULT_PORT),
            "127.0.0.1:" + str(DEFAULT_PORT),
        ]
        return _pick(rng, choices)
    return "localhost"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Compose possibly multiple candidates separated by newlines or commas to explore tokenization,
    # but primary target uses a single string; keep to a single address most of the time.
    if rng.random() < 0.85:
        s = _gen_hostport(rng)
    else:
        # Generate a small list for variety in some harnesses
        count = _rand_int(rng, 2, 4)
        sep = _pick(rng, [",", "\n", " "])
        s = sep.join(_gen_hostport(rng) for _ in range(count))
    data = s.encode("utf-8", errors="strict")
    if len(data) > MAX_LEN:
        data = data[:MAX_LEN]
    return data

import random
import string
from typing import List

# Target data type: "integer string" used for seconds/timeouts
# We generate ASCII strings that parsers commonly accept for integer values,
# including interesting edge cases, signs, whitespace, base prefixes, limits,
# and mixed-valid forms that libraries may partially parse.

_MAX_LEN = 32  # fuzzer truncates to 32, stay within that


def _rand_spaces(rng: random.Random) -> str:
    # Mix of spaces, tabs, other ASCII spaces commonly treated as whitespace
    ws_chars = [' ', '\t', '\n', '\r', '\v', '\f']
    return ''.join(rng.choice(ws_chars) for _ in range(rng.randint(0, 4)))


def _with_optional_sign(rng: random.Random) -> str:
    return rng.choice(['', '+', '-', '++', '--', '+-', '-+']) if rng.random() < 0.7 else ''


def _digits(rng: random.Random, min_len: int = 1, max_len: int = 19) -> str:
    n = rng.randint(min_len, max_len)
    # Sometimes produce leading zeros
    if rng.random() < 0.3:
        n = max(n, 2)
        return '0' * rng.randint(1, min(6, n - 1)) + ''.join(rng.choice(string.digits) for _ in range(n - 1))
    return ''.join(rng.choice(string.digits) for _ in range(n))


def _bounded_number(rng: random.Random) -> str:
    # Values around common boundaries for timeouts
    interesting = [
        '0', '1', '2', '9', '10', '59', '60', '61', '120', '300',
        str(2**31 - 1), str(2**31), str(2**31 + 1),
        str(2**63 - 1), str(2**63),
    ]
    val = rng.choice(interesting)
    if rng.random() < 0.5:
        val = _with_optional_sign(rng) + val
    return val


def _hex_like(rng: random.Random) -> str:
    # Some parsers accept 0x...; for decimal-only parsers this should fail gracefully
    n = rng.randint(1, 8)
    payload = ''.join(rng.choice('0123456789abcdefABCDEF') for _ in range(n))
    return _with_optional_sign(rng) + '0x' + payload


def _octal_like(rng: random.Random) -> str:
    n = rng.randint(1, 8)
    payload = ''.join(rng.choice('01234567') for _ in range(n))
    # Leading zero style (e.g., 0755)
    return _with_optional_sign(rng) + '0' + payload


def _decimal_with_trailing(rng: random.Random) -> str:
    core = _with_optional_sign(rng) + _digits(rng, 1, 10)
    # Add benign trailing content that some parsers stop before (e.g., "10s", "10#")
    tails = ['s', 'S', 'sec', ' seconds', '#', ';', ',', ' ms', 'abc']
    tail = rng.choice(tails)
    return core + tail


def _empty_or_ws(rng: random.Random) -> str:
    return '' if rng.random() < 0.5 else _rand_spaces(rng)


def _composed_integer_string(rng: random.Random) -> str:
    # Compose with leading/trailing whitespace and optional sign
    parts: List[str] = []
    parts.append(_rand_spaces(rng))

    # Choose a core form
    choice = rng.random()
    if choice < 0.30:
        core = _bounded_number(rng)
    elif choice < 0.55:
        core = _with_optional_sign(rng) + _digits(rng, 1, rng.randint(1, 19))
    elif choice < 0.65:
        core = _hex_like(rng)
    elif choice < 0.75:
        core = _octal_like(rng)
    elif choice < 0.85:
        core = _decimal_with_trailing(rng)
    elif choice < 0.92:
        # Very large or very small values (with many digits)
        core = _with_optional_sign(rng) + _digits(rng, 20, 40)
    else:
        core = _empty_or_ws(rng)

    parts.append(core)
    parts.append(_rand_spaces(rng))

    s = ''.join(parts)
    # Limit length
    if len(s) > _MAX_LEN:
        s = s[:_MAX_LEN]
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Prepare a small corpus of fixed-interest cases and then pick one or synthesize
    corpus = [
        '', '0', '1', '-1', '+1', ' 0 ', '  10', '\t42', '060', '0x2A', '  0xFF  ',
        '60', '59', '61', '300', '999999999', str(2**31 - 1), str(2**31),
        str(2**63 - 1), '-0', '+0', '10s', ' 15 sec', '  -5  ',
        '   ', '\n\t', 'abc', '--3', '++7', '+-8', '-+9', '18446744073709551615',
    ]

    if rng.random() < 0.5:
        s = rng.choice(corpus)
    else:
        s = _composed_integer_string(rng)

    # Ensure final size constraint
    if len(s) > _MAX_LEN:
        s = s[:_MAX_LEN]

    # Return as bytes (ASCII)
    return s.encode('ascii', errors='ignore')

import random
import string
from typing import List

# Generator for valid NUT device-name-centric inputs to exercise MemClientStub fuzzers.
# FUZZ_PARAM_STR in these stubs feeds device names, variable names, and values.
# We craft a bytes payload that the fuzzing harness will split into multiple strings.
# The content emphasizes realistic NUT identifiers: alphanumerics with '.', '-', '_', and ':'
# plus a mix of ASCII tokens that look like variable names and values.

SAFE_CHARS = string.ascii_letters + string.digits + "._-:"
VAR_NAME_CHARS = string.ascii_lowercase + string.digits + "._-"
VALUE_CHARS = string.ascii_letters + string.digits + " ._-/:%+[](){}<>#=,"

# Some common/interesting device and variable names seen in NUT environments
COMMON_DEVS = [
    "ups", "ups1", "main-ups", "rack.ups", "core:ups", "pdu-01", "srv-ups", "lab_ups",
]
COMMON_VARS = [
    "ups.status", "battery.charge", "battery.runtime", "input.voltage", "output.voltage",
    "ups.load", "driver.version", "device.mfr", "device.model", "ups.test.result",
]
COMMON_CMDS = [
    "test.battery.start", "test.battery.stop", "shutdown.return", "shutdown.stayoff",
    "beeper.enable", "beeper.disable"
]


def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]


def _rand_dev(rng: random.Random) -> str:
    # 50% pick a common device, 50% synthesize
    if rng.random() < 0.5:
        base = _rand_choice(rng, COMMON_DEVS)
    else:
        length = rng.randint(3, 24)
        base = ''.join(rng.choice(SAFE_CHARS) for _ in range(length))
        # ensure starts alnum for nicer parsing
        if not base[0].isalnum():
            base = 'u' + base[1:]
    # Occasionally append a numeric suffix
    if rng.random() < 0.3:
        base += str(rng.randint(0, 99))
    return base[:64]


def _rand_var(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return _rand_choice(rng, COMMON_VARS)
    parts = rng.randint(1, 3)
    tokens = []
    for _ in range(parts):
        ln = rng.randint(2, 12)
        tokens.append(''.join(rng.choice(VAR_NAME_CHARS) for _ in range(ln)))
    return '.'.join(tokens)[:64]


def _rand_value(rng: random.Random) -> str:
    if rng.random() < 0.5:
        # numeric-like
        if rng.random() < 0.5:
            return str(rng.randint(0, 10000))
        else:
            return f"{rng.randint(0, 300)}.{rng.randint(0, 999):03d}"
    if rng.random() < 0.3:
        # status-like tokens
        return _rand_choice(rng, [
            "OL", "OB", "LB", "CHRG", "DISCHRG", "ALARM", "CAL", "TRIM", "BOOST",
            "OL CHRG", "OB DISCHRG", "ALARM LB"
        ])
    ln = rng.randint(1, 48)
    return ''.join(rng.choice(VALUE_CHARS) for _ in range(ln))


def _rand_cmd(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return _rand_choice(rng, COMMON_CMDS)
    # synthesize command-like
    parts = rng.randint(1, 3)
    tokens = []
    for _ in range(parts):
        ln = rng.randint(2, 10)
        tokens.append(''.join(rng.choice(VAR_NAME_CHARS) for _ in range(ln)))
    return '.'.join(tokens)


def _make_corpus(rng: random.Random) -> List[str]:
    corpus: List[str] = []

    # Primary device name used by most stubs
    dev = _rand_dev(rng)
    corpus.append(dev)

    # Additional devices for getDevicesVariableValues set-building
    for _ in range(rng.randint(0, 3)):
        corpus.append(_rand_dev(rng))

    # Variable names and values for set/get paths
    for _ in range(rng.randint(2, 6)):
        corpus.append(_rand_var(rng))
    for _ in range(rng.randint(2, 6)):
        corpus.append(_rand_value(rng))

    # Include some command-like tokens (even if not used by these stubs, harmless and may be reused as names/values)
    for _ in range(rng.randint(1, 3)):
        corpus.append(_rand_cmd(rng))

    # Mix in duplicates and near-duplicates to exercise set uniqueness in stubs
    if rng.random() < 0.5:
        corpus.append(dev)
    if rng.random() < 0.4:
        corpus.append(dev + "-bak")

    # Ensure all strings are within bounds expected by stubs
    corpus = [s[:128] for s in corpus]
    return corpus


def _serialize_strings(strings: List[str], rng: random.Random) -> bytes:
    # Use length-prefixed segments to be robust for FUZZ_PARAM_STR consumers.
    # Format: sequence of [u16_le length][utf-8 bytes]
    # Also prepend an attribute block that the harness may consume as object attrs
    out = bytearray()

    # Attribute map for object under test; fuzzer checks attr kind=="mem_client"
    # We serialize a tiny header: magic b"ATTR\0", count u8, then pairs [klen u8][k][vlen u8][v]
    attrs = {"kind": "mem_client"}
    out += b"ATTR\x00"
    out.append(len(attrs) & 0xFF)
    for k, v in attrs.items():
        kb = k.encode('utf-8')
        vb = v.encode('utf-8')
        out.append(len(kb) & 0xFF)
        out += kb
        out.append(len(vb) & 0xFF)
        out += vb

    # Now the string stream
    for s in strings:
        b = s.encode('utf-8')
        if len(b) > 512:
            b = b[:512]
        out += len(b).to_bytes(2, 'little')
        out += b

    # Cap to 4096 bytes
    return bytes(out[:4096])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    strings = _make_corpus(rng)
    # Randomly shuffle to diversify consumption order across calls
    rng.shuffle(strings)
    return _serialize_strings(strings, rng)
